from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, EncryptionAlgorithm


def decrypt_payload(payload, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            response = client.decrypt(EncryptionAlgorithm.a256_gcm, payload['ciphertext'], payload['iv'], payload['tag'])
    return {'plaintext': response.plaintext, 'key_id': response.key_id, 'algorithm': 'A256GCM'}

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, EncryptionAlgorithm


def envelope_encrypt(plaintext, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            data_key = client.encrypt(EncryptionAlgorithm.rsa_oaep, plaintext[:32])
            encrypted_data_key = client.encrypt(EncryptionAlgorithm.a256_gcm, data_key.ciphertext)
            encrypted_plaintext = client.encrypt(EncryptionAlgorithm.a256_gcm, plaintext[32:])
    return {'encrypted_data_key': encrypted_data_key.ciphertext, 'encrypted_plaintext': encrypted_plaintext.ciphertext, 'iv': encrypted_plaintext.iv, 'tag': encrypted_plaintext.authentication_tag, 'key_id': encrypted_plaintext.key_id, 'algorithm': 'A256GCM'}

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, SignatureAlgorithm


def sign_or_verify_key(payload, action, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            if action == 'sign':
                response = client.sign(SignatureAlgorithm.rsassa_pss, payload['plaintext'])
                return {'signature': response.signature, 'key_id': response.key_id, 'algorithm': 'RS256'}
            elif action == 'verify':
                response = client.verify(SignatureAlgorithm.rsassa_pss, payload['plaintext'], payload['signature'])
                return {'is_valid': response.is_valid, 'key_id': response.key_id, 'algorithm': 'RS256'}
            else:
                raise ValueError('Invalid action. Must be either sign or verify.')

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys import KeyClient


def get_client(config):
    return KeyClient(config['vault_url'], DefaultAzureCredential())

from typing import Any, Dict


def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {k: v for k, v in payload.items() if v is not None}


def parse_response(response: Dict[str, Any]) -> Dict[str, Any]:
    return {k: v for k, v in response.items() if v is not None}

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys import KeyClient


def key_usage_summary(config):
    client = KeyClient(config['vault_url'], DefaultAzureCredential())
    keys = client.list_properties_of_keys()
    usage_summary = {}
    for key in keys:
        usage_summary[key.name] = key.attributes.enabled
    return usage_summary

import re


def payload_safety(payload):
    unsafe_patterns = [r'<script>', r'<img', r'<iframe', r'<object', r'<embed']
    for pattern in unsafe_patterns:
        if re.search(pattern, payload):
            return False
    return True
